t AS (SELECT column1 AS ti, column2 AS territory, column3 AS fw, column4 AS district, column5 AS home_city, column6 AS home_st, column7 AS home_zip, column8 AS fw_model, column9 AS fps, column10 AS producers, column11 AS terr_before FROM VALUES (0,'3104','Tobias Reyes','District 1','Fresno','CA','93750','Inside',62,68,'3175'),(1,'3107','Rory Eastman','District 1','Concord','CA','94522','Field',57,29,'3147'),(2,'3109','Mira Okafor','District 1','Lancaster','CA','93534','Hybrid',51,33,'3169'),(3,'3112','Ines Moreau','District 1','Los Angeles','CA','90036','Hybrid',62,78,'3134'),(4,'3118','Priya Nand','District 2','Trabuco Canyon','CA','92678','Inside',24,62,'3159'),(5,'3121','Lena Marsh','District 2','Honolulu','HI','96810','Inside',57,57,'3137'),(6,'3126','Owen Castellan','District 2','Marshall','CA','94940','Hybrid',41,20,'3169'),(7,'3133','Noor Ibrahim','District 2','Sugarloaf','CA','92386','Inside',28,96,'3142'),(8,'4202','Elena Voss','District 3','Salt Lake City','UT','84103','Inside',47,37,'4213'),(9,'4205','Hector Dalton','District 3','El Paso','TX','79998','Hybrid',29,13,'4277'),(10,'4208','Julian Brandt','District 3','Picacho','AZ','85141','Hybrid',74,52,'4282'),(11,'4211','Caleb Whitford','District 3','Hayden','CO','81639','Inside',74,96,'4237'),(12,'5103','Marcus Hale','District 4','Joyce','WA','98343','Inside',59,13,'5180'),(13,'5106','Sofia Landry','District 4','Kerby','OR','97531','Inside',40,35,'5175'),(14,'5110','Dario Quinn','District 4','Anchorage','AK','99513','Field',56,17,'5157'),(15,'5114','Vivian Cho','District 4','Herman','NE','68029','Field',74,91,'5145')),
ch AS (SELECT column1 AS ch FROM VALUES ('FI'),('IP'),('RW'),('Unknown')),
lob AS (SELECT column1 AS lob FROM VALUES ('FA'),('IA'),('IOVA'),('MF'),('RILA'),('SA'),('TA'),('VA'),('Total')),
g AS (SELECT z.zip, z.city, z.st, z.ti, ch.ch FROM z JOIN ch ON (ch.ch <> 'Unknown' OR z.unk = 1)),
b AS (
  SELECT g.zip, g.city, g.st, g.ti, g.ch, l.lob,
    CASE WHEN g.ch = 'Unknown' OR l.lob IN ('MF','Total') OR (MOD(ABS(HASH(g.zip,g.ch,'act')),1000003)/1000003.0) > 0.22 OR (MOD(ABS(HASH(g.zip,g.ch,l.lob,'lob')),1000003)/1000003.0) > 0.6 THEN 0
         ELSE ROUND(EXP(13.7 + 3.4*((MOD(ABS(HASH(g.zip,g.ch,l.lob,'o1')),1000003)/1000003.0)+(MOD(ABS(HASH(g.zip,g.ch,l.lob,'o2')),1000003)/1000003.0)+(MOD(ABS(HASH(g.zip,g.ch,l.lob,'o3')),1000003)/1000003.0)-1.5)), 2) END AS opp,
    (MOD(ABS(HASH(g.zip,g.ch,l.lob,'s1')),1000003)/1000003.0) AS s1, (MOD(ABS(HASH(g.zip,g.ch,l.lob,'s2')),1000003)/1000003.0) AS s2,
    CASE WHEN g.ch = 'Unknown' THEN 0 WHEN (MOD(ABS(HASH(g.zip,g.ch,'act')),1000003)/1000003.0) <= 0.22 THEN FLOOR(1 + 28*POWER((MOD(ABS(HASH(g.zip,g.ch,'m1')),1000003)/1000003.0),2)) WHEN (MOD(ABS(HASH(g.zip,g.ch,'m2')),1000003)/1000003.0) < 0.04 THEN FLOOR(1 + 4*(MOD(ABS(HASH(g.zip,g.ch,'m3')),1000003)/1000003.0)) ELSE 0 END AS mtgs
  FROM g CROSS JOIN lob l
),
c AS (
  SELECT b.*, MAX(CASE WHEN lob <> 'Total' THEN opp END) OVER (PARTITION BY zip, ch) AS max_opp FROM b
)
SELECT
  t.fw AS "FW", 'Dana Whitaker' AS "RSM", t.territory AS "Territory", c.ch AS "Channel", c.lob AS "Product LOB",
  c.zip AS "Zip Code", c.city AS "CITY", c.st AS "STATE", 'West' AS "Region",
  'Territory ' || t.territory AS "Description", t.district AS "District", t.fps AS "FPs",
  t.home_city AS "FW Home City", 'County ' || MOD(ABS(HASH(t.home_zip)),60) AS "FW Home County", t.home_st AS "FW Home State", t.home_zip AS "FW Home Zip",
  t.fw_model AS "FW Model",
  CASE WHEN c.lob = 'Total' THEN COALESCE(c.max_opp,0) ELSE c.opp END::FLOAT AS "MM Opp",
  CASE WHEN c.lob IN ('Total','MF') OR c.opp = 0 OR c.s1 > 0.3 THEN 0 ELSE ROUND(c.opp*(0.015 + 0.3*c.s2), 0) END::FLOAT AS "MM Sales",
  c.mtgs::FLOAT AS "Mtgs", 'Graham Ellery' AS "NSM",
  (ROUND(c.s2*1000000, 0))::FLOAT AS "PL Sales", t.producers AS "Producers", t.terr_before AS "Territory Before", 'Current' AS "Version",
  'County ' || MOD(ABS(HASH(c.zip)),400) AS "COUNTY"
FROM c JOIN t ON c.ti = t.ti